import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    if k > n - 1:
        print(-1)
        return

    m = n * k
    matches = []

    for i in range(1, n + 1):
        for j in range(k):
            next_team = (i + j) % n + 1
            if next_team == i:
                next_team = (next_team + 1) % n + 1
            matches.append((i, next_team))

    print(m)
    for match in matches:
        print(match[0], match[1])

if __name__ == "__main__":
    main()
